sys_script_include.script:
var DoctorRequestUtils = Class.create();
DoctorRequestUtils.prototype = Object.extendsObject(AbstractAjax, {

    /**
     * Doctor Field Reference Qualifier
     * @param {Object} current - Current Doctor Request record
     * @returns {String} Encoded Query string
     */
    getDoctorRefQual: function(current) {
        if (!current || !current.request_type) return '';

        var currentHospital = current.hospital; // Adjust field name if different (e.g., current.u_hospital)
        var reqType = current.request_type.toString().toLowerCase();

        // Leave: Current hospital ke hi doctors show honge
        if (reqType === 'leave') {
            return 'primary_hospital=' + currentHospital;
        } 
        // Cover: Doctors jinka primary hospital current hospital NAHI hai
        else if (reqType === 'cover') {
            return 'primary_hospital!=' + currentHospital;
        }

        return '';
    },

    /**
     * Approval Group Field Reference Qualifier
     * @param {Object} current - Current Doctor Request record
     * @returns {String} Encoded Query string
     */
    getApprovalGroupRefQual: function(current) {
        if (!current || !current.request_type) return '';

        var reqType = current.request_type.toString().toLowerCase();

        if (reqType === 'cover') {
            // Agar Cover request hai aur doctor selected hai, to doctor ke hospital ka approver group fetch karo
            var coverHospitalCode = '';

            if (current.doctor && current.doctor.hospital) {
                // Doctor ke reference record se hospital code read kar rahe hain
                coverHospitalCode = current.doctor.hospital.number; // Adjust 'code' field name on Hospital table
            }

            if (coverHospitalCode) {
                // Group naming convention search: e.g., 'HOSP_CODE_Approvers' ya name contains hospital code
                return 'nameLIKE' + coverHospitalCode;
            }
        }

        return ''; // Leave request ya default case me custom logic/all groups
    },

    /**
     * Approver Field Reference Qualifier
     * @param {Object} current - Current Doctor Request record
     * @returns {String} Encoded Query string
     */
    getApproverRefQual: function(current) {
        if (!current || !current.request_type) return '';

        var reqType = current.request_type.toString().toLowerCase();

        // 1. Cover: Selected approval_group ke active members show honge
        if (reqType === 'cover') {
            if (current.approval_group) {
                return 'sys_idIN' + this._getGroupMembers(current.approval_group);
            }
        } 
        // 2. Leave: Auto HOD + Reports To Backup
        else if (reqType === 'leave') {
            var doctorId = current.doctor;
            if (!doctorId) return '';

            var doctorGr = new GlideRecord('sys_user'); // Assuming doctor is in sys_user / doctor table
            if (doctorGr.get(doctorId)) {
                var approvers = [];

                // Primary Approver: Department HOD
                if (doctorGr.department && doctorGr.department.dept_head) {
                    approvers.push(doctorGr.department.dept_head.toString());
                }

                // Backup Approver: Manager / Reports-To
                if (doctorGr.manager) {
                    approvers.push(doctorGr.manager.toString());
                }

                if (approvers.length > 0) {
                    return 'sys_idIN' + approvers.join(',');
                }
            }
        }

        return '';
    },

    /**
     * Helper Function: Fetch Group Member sys_ids
     */
    _getGroupMembers: function(groupId) {
        var members = [];
        var grMember = new GlideRecord('sys_user_grmember');
        grMember.addQuery('group', groupId);
        grMember.query();
        while (grMember.next()) {
            members.push(grMember.getValue('user'));
        }
        return members.join(',');
    },

    type: 'DoctorRequestUtils'
});
